import { LivePointsFileSchema } from '@jaga-daerah/contracts';
import type { LivePoint } from '@jaga-daerah/contracts';

// Relative: the `#api/*` subpath map appends `.ts`.
import pointsJson from '../data/live-points.json';

// Static per-region reference for the live feeds, generated by `bun run etl:live-points` from the
// pinned Kemendagri code list, the reviewed sample points, and the boundary outlines. Bundled with
// the Worker so a live request needs no database round trip; parsed once, on first use.
export type RegionLivePoint = LivePoint & { slug: string };

let points: Map<string, RegionLivePoint> | undefined;

/** The live reference for a region slug, or undefined for an unknown slug. */
export function findLivePoint(slug: string): RegionLivePoint | undefined {
  points ??= new Map(
    Object.entries(LivePointsFileSchema.parse(pointsJson).regions).map(([key, point]) => [
      key,
      { ...point, slug: key },
    ]),
  );
  return points.get(slug);
}
